INSERT INTO departamentos (id, clave, nombre, area_id, origen_mo) SELECT MAX(id) + 1, 'coordinacion_posgrado_mci', 'Coordinación de la Maestría en Ciencias de la Ingeniería', 3, 'Alta en la plataforma (Subdirección Académica, nov 2026)' FROM departamentos WHERE NOT EXISTS (SELECT 1 FROM departamentos WHERE clave = 'coordinacion_posgrado_mci');
