INSERT INTO programa_organos (programa_id, tipo, nombre, activo) SELECT p.id, t.tipo, CONCAT(t.tipo, ' de ', p.siglas), 1 FROM programas p JOIN (SELECT 'NAB' AS tipo UNION ALL SELECT 'CAP') t WHERE p.nivel = 'posgrado' AND NOT EXISTS (SELECT 1 FROM programa_organos o WHERE o.programa_id = p.id AND o.tipo = t.tipo);
INSERT INTO usuario_roles (usuario_id, rol, departamento_id, programa_id, cargo) SELECT pr.usuario_id, 'coordinador', d.id, pr.programa_id, 'titular' FROM programa_responsables pr JOIN programas p ON p.id = pr.programa_id AND p.nivel = 'posgrado' JOIN departamentos d ON d.clave = CONCAT('coordinacion_posgrado_', LOWER(p.siglas)) WHERE pr.cargo = 'coordinador' AND pr.activo = 1 AND NOT EXISTS (SELECT 1 FROM usuario_roles r WHERE r.usuario_id = pr.usuario_id AND r.rol = 'coordinador' AND r.departamento_id = d.id);
